	 * @since 8.0.0
	 */
	public function __construct(mixed $data = [], int $statusCode = Http::STATUS_OK, array $headers = []) {
		parent::__construct($statusCode, $headers);

		$this->data = $data;
	}

	/**
	 * Sets values in the data json array
	 * @psalm-suppress InvalidTemplateParam
