	}
}

/**
 * Prompts the user to download the a file
 * @since 7.0.0
 * @template-covariant S of Http::STATUS_*
 * @template-covariant C of string
 * @template-covariant H of array<string, mixed>
 * @template-extends Response<Http::STATUS_*, array<string, mixed>>
 */
class DownloadResponse extends Response {
	/**
	 * Creates a response that prompts the user to download the file
	 * @param string $filename the name that the downloaded file should have
	 * @param C $contentType the mimetype that the downloaded file should have
	 * @param S $status
	 * @param H $headers
	 * @since 7.0.0
	 */
	public function __construct(string $filename, string $contentType, int $status = Http::STATUS_OK, array $headers = []) {
		parent::__construct($status, $headers);

		$sanitized = str_replace(['/', '\\'], '-', $filename);
		$fallback = str_replace('%', '', (new UnicodeString($sanitized))->ascii()->toString());
		$this->addHeader('Content-Disposition', HeaderUtils::makeDisposition(HeaderUtils::DISPOSITION_ATTACHMENT, $sanitized, $fallback));
		$this->addHeader('Content-Type', $contentType);
	}
}

/**
 * Class FileDisplayResponse
 *
 * @since 11.0.0
 * @template-covariant S of Http::STATUS_*
 * @template-covariant H of array<string, mixed>
 * @template-extends Response<Http::STATUS_*, array<string, mixed>>
 */
class FileDisplayResponse extends Response implements ICallbackResponse {
	private File|ISimpleFile $file;

	/**
	 * FileDisplayResponse constructor.
	 *
	 * @param File|ISimpleFile $file
	 * @param S $statusCode
	 * @param H $headers
	 * @since 11.0.0
	 */
	public function __construct(File|ISimpleFile $file, int $statusCode = Http::STATUS_OK, array $headers = []) {
		parent::__construct($statusCode, $headers);

		$this->file = $file;
		$this->addHeader('Content-Disposition', 'inline; filename="' . rawurldecode($file->getName()) . '"');

		$this->setETag($file->getEtag());
		$lastModified = new \DateTime();
		$lastModified->setTimestamp($file->getMTime());
		$this->setLastModified($lastModified);
	}

	/**
	 * @param IOutput $output
	 * @since 11.0.0
	 */
	#[\Override]
	public function callback(IOutput $output) {
		if ($output->getHttpResponseCode() !== Http::STATUS_NOT_MODIFIED) {
			$file = $this->file instanceof File
				? $this->file->fopen('rb')
				: $this->file->read();

			if ($file === false) {
				$output->setHttpResponseCode(Http::STATUS_NOT_FOUND);
				$output->setOutput('');
				return;
			}

			$output->setHeader('Content-Length: ' . $this->file->getSize());
			$output->setReadfile($file);
		}
	}
}

/**
 * A renderer for JSON calls
 * @since 6.0.0
 * @template-covariant S of Http::STATUS_*
 * @template-covariant T of null|string|int|float|bool|array|\stdClass|\JsonSerializable
 * @template-covariant H of array<string, mixed>
 * @template-extends Response<Http::STATUS_*, array<string, mixed>>
 */
class JSONResponse extends Response {
	/**
	 * response data
	 * @var T
	 */
	protected $data;
	/**
	 * Additional `json_encode` flags
	 * @var int
	 */
	protected $encodeFlags;

	/**
	 * constructor of JSONResponse
	 * @param T $data the object or array that should be transformed
	 * @param S $statusCode the Http status code, defaults to 200
	 * @param H $headers
	 * @param int $encodeFlags Additional `json_encode` flags
	 * @since 6.0.0
	 * @since 30.0.0 Added `$encodeFlags` param
	 */
	public function __construct(
		mixed $data = [],
		int $statusCode = Http::STATUS_OK,
		array $headers = [],
		int $encodeFlags = 0,
	) {
		parent::__construct($statusCode, $headers);

		$this->data = $data;
		$this->encodeFlags = $encodeFlags;
		$this->addHeader('Content-Type', 'application/json; charset=utf-8');
	}

	/**
	 * Returns the rendered json
	 * @return string the rendered json
	 * @since 6.0.0
	 * @throws \Exception If data could not get encoded
	 *
	 * @psalm-taint-escape has_quotes
	 * @psalm-taint-escape html
	 */
	#[\Override]
	public function render() {
		/** @psalm-suppress FalsableReturnStatement */
		return json_encode($this->data, JSON_HEX_TAG | JSON_THROW_ON_ERROR | $this->encodeFlags, 2048);
	}

	/**
	 * Sets values in the data json array
	 * @psalm-suppress InvalidTemplateParam
	 * @param T $data an array or object which will be transformed
	 *                to JSON
	 * @return JSONResponse Reference to this object
	 * @since 6.0.0 - return value was added in 7.0.0
	 */
	public function setData($data) {
		$this->data = $data;

		return $this;
	}

	/**
	 * @return T the data
	 * @since 6.0.0
	 */
	public function getData() {
		return $this->data;
	}
}

public function manageOCMRequests(string $ocmPath): Response {
	if (!mb_check_encoding($ocmPath, 'UTF-8')) {
		throw new OCMArgumentException('path is not UTF-8');
	}

	$ocmAddress = null;
	$params = $this->request->getParams();
	foreach (['owner', 'sender', 'sharedBy'] as $field) {
		if (is_string($params[$field] ?? null) && $params[$field] !== '') {
			$ocmAddress = $params[$field];
			break;
		}
	}

	try {
		$signedRequest = $this->ocmDiscoveryService->getIncomingSignedRequest($ocmAddress);
	} catch (IncomingRequestException $e) {
		$this->logger->warning('incoming ocm request exception', ['exception' => $e]);
		$response = new JSONResponse(['message' => $e->getMessage(), 'validationErrors' => []], Http::STATUS_BAD_REQUEST);
		$response->throttle();
		return $response;
	}

	// assuming that ocm request contains a json array
	$payload = $signedRequest?->getBody() ?? file_get_contents('php://input');
	try {
		$payload = ($payload) ? json_decode($payload, true, 512, JSON_THROW_ON_ERROR) : null;
	} catch (JsonException $e) {
		$this->logger->debug('json decode error', ['exception' => $e]);
		$payload = null;
	}

	$event = new OCMEndpointRequestEvent(
		$this->request->getMethod(),
		preg_replace('@/+@', '/', $ocmPath),
		$payload,
		$signedRequest?->getOrigin()
	);
	$this->eventDispatcher->dispatchTyped($event);

	return $event->getResponse() ?? new Response(Http::STATUS_NOT_FOUND);
}

